package com.aredth.autopay;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import org.springframework.beans.factory.annotation.Value;
import java.math.*;
import java.time.*;
import java.util.*;
@Service
@Transactional
class InvoiceService {
 record Item(@NotBlank @Size(max=250) String description,@Min(1) @Max(10000) int quantity,@NotNull @DecimalMin("0.01") @DecimalMax("1000000") @Digits(integer=7,fraction=2) BigDecimal unitPrice){}
 record Draft(@NotBlank @Size(max=150) String client,@NotBlank @Email @Size(max=200) String email,@Pattern(regexp="^$|\\+[1-9][0-9]{7,14}$") String phone,@NotNull LocalDate dueDate,@Size(max=2000) String notes,@NotEmpty @Size(max=50) List<@Valid Item> items){}
 private final InvoiceRepository repo; private final AttemptRepository attempts; private final boolean live;
 InvoiceService(InvoiceRepository r,AttemptRepository a,@Value("${autopay.live}") boolean l){repo=r;attempts=a;live=l;}
 Invoice get(UUID id){return repo.findById(id).filter(i->!i.deleted).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Invoice not found"));}
 Invoice lock(UUID id){return repo.locked(id).filter(i->!i.deleted).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Invoice not found"));}
 List<Invoice> all(){return repo.findAll().stream().filter(i->!i.deleted).sorted(Comparator.comparing((Invoice i)->i.createdAt).reversed()).toList();}
 Invoice create(Draft d){Invoice i=new Invoice();i.client=d.client().trim();i.email=d.email().trim().toLowerCase(Locale.ROOT);i.phone=d.phone()==null?"":d.phone();i.dueDate=d.dueDate();i.notes=d.notes();i.total=BigDecimal.ZERO;for(Item line:d.items()){i.items.add(new Invoice.Line(line.description().trim(),line.quantity(),line.unitPrice()));i.total=i.total.add(line.unitPrice().multiply(BigDecimal.valueOf(line.quantity())));}i.total=i.total.setScale(2,RoundingMode.UNNECESSARY);if(i.total.compareTo(new BigDecimal("10000000"))>0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invoice total exceeds limit");i.event("Invoice created");return repo.save(i);}
 List<Invoice> trash(){return repo.findAll().stream().filter(i->i.deleted).sorted(Comparator.comparing((Invoice i)->i.createdAt).reversed()).toList();}
 Invoice delete(UUID id){Invoice i=lock(id);if(attempts.existsByInvoiceIdAndStateIn(id,List.of("CREATED","CALLING","UNKNOWN")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Payment call is active or unresolved");i.deleted=true;i.event("Invoice moved to trash");return i;}
 Invoice restore(UUID id){Invoice i=repo.locked(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!i.deleted)throw new ResponseStatusException(HttpStatus.CONFLICT,"Invoice is not in trash");i.deleted=false;i.event("Invoice restored from trash");return i;}
 record Update(@NotNull @Valid Draft invoice,@NotBlank @Size(max=80) String number,@NotNull @Pattern(regexp="OPEN|PAID|VOID") String status,LocalDate paymentDate,@Pattern(regexp="CHECK|ACH|BANK_TRANSFER|CARD|CASH|OTHER|DEMO") String paymentMethod,@Size(max=80) String checkNumber){}
 Invoice update(UUID id,Update d){Invoice i=lock(id);if(attempts.existsByInvoiceIdAndStateIn(id,List.of("CREATED","CALLING","UNKNOWN")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Invoice has an active or unresolved payment call");String number=d.number().trim();if(repo.findAll().stream().anyMatch(other->!other.id.equals(id)&&other.number.equalsIgnoreCase(number)))throw new ResponseStatusException(HttpStatus.CONFLICT,"Invoice number already exists");if(d.status().equals("PAID")&&!i.status.equals("PAID")&&(d.paymentDate()==null||d.paymentMethod()==null))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Paid invoices need a payment date and method");if(d.status().equals("PAID")&&"CHECK".equals(d.paymentMethod())&&(d.checkNumber()==null||d.checkNumber().isBlank()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A check number is required");Draft v=d.invoice();BigDecimal amount=BigDecimal.ZERO;List<Invoice.Line> lines=new ArrayList<>();for(Item line:v.items()){amount=amount.add(line.unitPrice().multiply(BigDecimal.valueOf(line.quantity())));lines.add(new Invoice.Line(line.description().trim(),line.quantity(),line.unitPrice()));}if(amount.compareTo(new BigDecimal("10000000"))>0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invoice total exceeds limit");i.number=number;i.client=v.client().trim();i.email=v.email().trim().toLowerCase(Locale.ROOT);i.phone=v.phone()==null?"":v.phone();i.dueDate=v.dueDate();i.notes=v.notes();i.items.clear();i.items.addAll(lines);i.total=amount.setScale(2,RoundingMode.UNNECESSARY);i.status=d.status();i.paymentDate=d.status().equals("PAID")?d.paymentDate():null;i.paymentMethod=d.status().equals("PAID")?d.paymentMethod():null;i.checkNumber=d.status().equals("PAID")&&"CHECK".equals(d.paymentMethod())?d.checkNumber().trim():null;i.event("Invoice edited manually — no money moved");return i;}
 Invoice paymentDetails(UUID id,String method,String checkNumber){Invoice i=lock(id);if(!i.status.equals("PAID"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Only paid invoices have payment details");if(method.equals("CHECK")&&checkNumber.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A check number is required");i.paymentMethod=method;i.checkNumber=method.equals("CHECK")?checkNumber.trim():null;i.event("Payment details updated");return i;}
 Invoice notes(UUID id,String notes){Invoice i=lock(id);i.notes=notes;i.event("Invoice notes updated");return i;}
 void open(Invoice i){if(!i.status.equals("OPEN"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Invoice is no longer open");}
 Invoice cancel(UUID id){Invoice i=lock(id);open(i);if(attempts.existsByInvoiceIdAndStateIn(id,List.of("CREATED","CALLING","UNKNOWN")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Payment call is active");i.status="VOID";i.event("Invoice voided");return i;}
 Invoice simulate(UUID id,String outcome){if(live)throw new ResponseStatusException(HttpStatus.CONFLICT,"Simulation disabled in live mode");Invoice i=lock(id);open(i);if(!List.of("success","failed").contains(outcome))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unknown outcome");i.event("DEMO: voice call simulated");if(outcome.equals("success")){i.status="PAID";i.paidAt=Instant.now();i.paymentDate=LocalDate.now(java.time.ZoneOffset.UTC);i.paymentMethod="DEMO";i.event("DEMO: payment recorded — no money moved");}else i.event("DEMO: payment failed — invoice remains open");return i;}
}
